public int getTransferType(String ext) {
	if (autoDetect) {
		Object obj = JFTP.prefs.getTransferTypes().get(ext);
		if (obj == null) {
			return JFTP.prefs.getDefaultTransferType();
		} else {
			return ((Integer) obj).intValue();
		}
	}
	return transferType;
}

