public static List getFavorites() throws IOException,
		ClassNotFoundException, IllegalBlockSizeException,
		BadPaddingException {
	List favorites = new ArrayList();
	FileInputStream fin = null;
	ObjectInputStream in = null;
	try {
		checkFavFile();
		fin = new FileInputStream(FAV_FILE);
		if (fin.available() > 0) {
			in = new ObjectInputStream(fin);
			Object obj = in.readObject();
			if (obj instanceof List) {
				favorites = (List) obj;
				saveFavorites(favorites);
			} else {
				SealedObject so = (SealedObject) obj;
				favorites = (List) so
						.getObject(getCipher(Cipher.DECRYPT_MODE));
			}
		}
		return favorites;
	} finally {
		try {
			if (in != null) {
				in.close();
			}
		} catch (IOException exp) {
		}
		try {
			if (fin != null) {
				fin.close();
			}
		} catch (IOException exp) {
		}
		in = null;
		fin = null;
	}
}

public void exit() {
	int sessionCount = tabs.getTabCount();
	for (int i = 0; i < sessionCount; i++) {
		FTPSession session = (FTPSession) tabs.getComponentAt(i);
		session.closeSession();
	}
	Rectangle windowBounds = getBounds();
	prefs.setWindowBounds(windowBounds);
	try {
		savePreferences(prefs);
	} catch (Exception exp) {
		// Ignore this.
	}
	dispose();
	System.gc();
	if (!applet) {
		System.exit(0);
	}
}

