	} catch (FTPException exp) {
		ftpException(exp);
	} catch (ConnectionException exp) {
		connectionException(exp);
	} catch (Exception exp) {
		statusWindow.addError("<ERROR> " + exp);
		exp.printStackTrace();
	} finally {
		timer.stop();
		timeElapsed = 0;
		statusBar.reset();
	}
}

